    title: "如果重来：一份发给 AI 就能精准落地的开发文档怎么写",
    lead: "针对复杂表格、弹层、字典这类功能。你之前累，是因为一开始各是各的实现，做着做着才发现都一样——应该先立范式再开发。但只立范式不够：范式管「怎么写」，管不了「写什么对」。所以一份能落地的文档必须两层分开：范式层（怎么写，硬化到能否决一种实现）+ 不变量层（写什么对，带否决条件）。范式层内部还有第一刀：一组表先打包成业务复合体，分档案复合体还是单据复合体——同一套表可以做档案管理、也可以被单据引用，行为完全两套，单表类型分不出这个差异，必须先在这一层分叉。再加一条：一次只给一个闭环。这是别人极简文档能成、你层层拉扯的真正分水岭。",
